{"cards": [{"node_code": "N_516a638401674b3f", "definition": "针对低空空域整体架构、基础设施布局及网络拓扑的系统性工程设计，包括起降场选址、空域划设及容量评估。", "boundary": "本节点聚焦于低空交通系统的物理与逻辑结构规划，属于工程与技术层面的顶层设计。边界在于区分“系统规划”与“政策法规”（后者侧重制度与合规）、“任务规划”（后者侧重单次飞行路径）。若内容涉及空域结构优化、起降点网络设计或系统容量仿真，归入本节点；若涉及具体法规条文解读，归入低空经济政策法规。", "includes": ["低空空域结构设计与划设方案", "起降场、充换电等基础设施布局规划", "低空交通网络容量评估与仿真分析"], "excludes": ["低空经济相关的宏观政策制定与法规解读", "单次无人机飞行的具体航线规划与避障策略"], "sibling_distinctions": [{"other_code": "N_6c7d24c16e71d984", "rule": "本节点侧重技术性的系统架构与设施布局规划；低空经济政策法规侧重制度性的法律、标准及经济政策制定。"}, {"other_code": "N_bec984076e4e123a", "rule": "本节点侧重宏观的系统级网络规划；无人机任务规划侧重微观的单体飞行器特定任务路径设计。"}], "cross_boundary_rule": "涉及空域划设时，若侧重技术可行性、容量匹配及设施配套，归入本节点；若侧重法律权限、审批流程及合规性要求，归入低空经济政策法规。"}, {"node_code": "N_6c7d24c16e71d984", "definition": "涵盖低空经济领域的法律法规、行业标准、适航审定规则及促进产业发展的政策体系研究。", "boundary": "本节点聚焦于低空交通运行的制度环境与合规框架，属于管理与政策层面。边界在于区分“政策法规”与“系统规划”（后者侧重技术布局）、“任务规划”（后者侧重操作执行）。若内容涉及民航法规解读、低空经济促进办法、适航标准或空域管理政策，归入本节点；若涉及具体的空域结构设计，归入低空交通系统规划。", "includes": ["低空空域管理法规与适航审定标准", "低空经济促进政策、补贴机制及产业规划", "低空交通运行规则与安全责任制度"], "excludes": ["低空交通基础设施的具体工程布局设计", "无人机飞行过程中的实时路径规划与避障算法"], "sibling_distinctions": [{"other_code": "N_516a638401674b3f", "rule": "本节点侧重制度规范与政策导向；低空交通系统规划侧重技术架构与设施布局。"}, {"other_code": "N_bec984076e4e123a", "rule": "本节点侧重宏观合规框架；无人机任务规划侧重微观任务执行前的路径设计。"}], "cross_boundary_rule": "涉及空域使用规则时，若侧重法律条文、审批权限及合规要求，归入本节点；若侧重基于规则的技术实现方案或网络优化，归入低空交通系统规划。"}, {"node_code": "N_bec984076e123a", "definition": "针对特定无人机作业任务（如巡检、测绘、物流）进行的航线设计、作业方案制定及资源预分配。", "boundary": "本节点聚焦于单次或批次飞行任务前的具体规划活动，属于操作执行层面。边界在于区分“任务规划”与“系统规划”（后者侧重宏观网络）、“政策法规”（后者侧重制度约束）。若内容涉及具体航线点设计、作业覆盖范围规划、电量/载荷预分配，归入本节点；若涉及实时飞行中的动态避障，归入低空运行与智能管控。", "includes": ["特定任务场景下的无人机航线与航点设计", "作业区域覆盖规划与资源（电量、载荷）预分配", "任务执行前的风险评估与应急预案制定"], "excludes": ["低空交通宏观网络架构与基础设施布局", "低空经济宏观政策制定与法律法规解读"], "sibling_distinctions": [{"other_code": "N_516a638401674b3f", "rule": "本节点侧重单体或批次任务的具体路径与作业方案；低空交通系统规划侧重宏观空域结构与设施网络。"}, {"other_code": "N_6c7d24c16e71d984", "rule": "本节点侧重任务执行前的技术规划；低空经济政策法规侧重任务执行的制度合规性。"}], "cross_boundary_